import{_ as a}from"./chunks/chat-diagnostics.HMJaz4jC.js";import{_ as t,o,c as n,ag as s}from"./chunks/framework.DqVSm8kp.js";const g=JSON.parse('{"title":"Chat Diagnostics","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/chat-diagnostics.md","filePath":"en/guide/chat-diagnostics.md"}'),i={name:"en/guide/chat-diagnostics.md"};function r(l,e,c,h,d,p){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="chat-diagnostics" tabindex="-1">Chat Diagnostics <a class="header-anchor" href="#chat-diagnostics" aria-label="Permalink to &quot;Chat Diagnostics&quot;">​</a></h1><p>The Chat Diagnostics page is the heart of LLMxRay. It combines a full-featured chat interface with deep, real-time analysis of every token the model produces.</p><p><strong>Sidebar item:</strong> Chat Diagnostics (first item) <strong>Route:</strong> <code>/</code></p><p><img src="'+a+'" alt="Chat Diagnostics interface"></p><h2 id="interface-overview" tabindex="-1">Interface Overview <a class="header-anchor" href="#interface-overview" aria-label="Permalink to &quot;Interface Overview&quot;">​</a></h2><p>The page is split into two areas:</p><ul><li><strong>Left panel</strong> — Session list showing all past conversations with timestamps, model names, and token counts.</li><li><strong>Right panel</strong> — Active chat area with message input, streaming output, and session detail tabs.</li></ul><h2 id="starting-a-conversation" tabindex="-1">Starting a Conversation <a class="header-anchor" href="#starting-a-conversation" aria-label="Permalink to &quot;Starting a Conversation&quot;">​</a></h2><ol><li>Select a model from the <strong>model dropdown</strong> at the top. Embedding models are automatically filtered out — only chat-capable models appear.</li><li>Type your message in the input area.</li><li>Press <strong>Enter</strong> or click Send.</li></ol><p>Tokens stream in one by one with <strong>confidence coloring</strong>: each token is tinted based on how quickly the model produced it. Faster tokens = higher confidence (greener). Slower tokens = lower confidence (more orange/red).</p><div class="info custom-block"><p class="custom-block-title">Confidence is an approximation</p><p>Since Ollama&#39;s <code>/api/chat</code> endpoint doesn&#39;t expose token logprobs, LLMxRay approximates confidence from inter-token latency. This is clearly labeled in the UI. For real logprobs, use the <a href="./benchmark.html">Benchmark</a> feature.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="markdown-rendering" tabindex="-1">Markdown Rendering <a class="header-anchor" href="#markdown-rendering" aria-label="Permalink to &quot;Markdown Rendering&quot;">​</a></h3><p>Model responses are rendered as rich markdown with syntax-highlighted code blocks.</p><h3 id="file-attachments" tabindex="-1">File Attachments <a class="header-anchor" href="#file-attachments" aria-label="Permalink to &quot;File Attachments&quot;">​</a></h3><p>Click the attachment button to upload files. For <strong>vision models</strong> (like LLaVA), you can paste or upload images directly — the model will analyze them.</p><h3 id="slash-commands" tabindex="-1">Slash Commands <a class="header-anchor" href="#slash-commands" aria-label="Permalink to &quot;Slash Commands&quot;">​</a></h3><p>Type <code>/</code> in the input to see available slash commands for quick actions.</p><h3 id="multi-turn-conversation" tabindex="-1">Multi-turn Conversation <a class="header-anchor" href="#multi-turn-conversation" aria-label="Permalink to &quot;Multi-turn Conversation&quot;">​</a></h3><p>Each conversation maintains full message history. The model sees all previous messages for context.</p><h2 id="session-deep-dive" tabindex="-1">Session Deep Dive <a class="header-anchor" href="#session-deep-dive" aria-label="Permalink to &quot;Session Deep Dive&quot;">​</a></h2><p>Click any session in the left panel to explore six analysis tabs:</p><h3 id="stream-tab" tabindex="-1">Stream Tab <a class="header-anchor" href="#stream-tab" aria-label="Permalink to &quot;Stream Tab&quot;">​</a></h3><p>Every token with timing data displayed in a scrollable list. Above the token list, a <strong>metrics dashboard</strong> shows:</p><ul><li><strong>TTFT</strong> (Time to First Token) — How long the model took to start responding</li><li><strong>Tokens/sec</strong> — Generation speed</li><li><strong>Total tokens</strong> — Prompt + completion token counts</li><li><strong>Latency chart</strong> — Visual timeline of inter-token delays</li></ul><h3 id="reasoning-tab" tabindex="-1">Reasoning Tab <a class="header-anchor" href="#reasoning-tab" aria-label="Permalink to &quot;Reasoning Tab&quot;">​</a></h3><p>If you&#39;re running a reasoning model like <strong>DeepSeek-R1</strong>, the <code>&lt;think&gt;</code> blocks are automatically parsed and displayed step by step. Each reasoning step is categorized as thought, observation, action, conclusion, or reflection.</p><h3 id="introspection-tab" tabindex="-1">Introspection Tab <a class="header-anchor" href="#introspection-tab" aria-label="Permalink to &quot;Introspection Tab&quot;">​</a></h3><p>Visualizations of layer activations, attention heatmaps, and model architecture.</p><div class="warning custom-block"><p class="custom-block-title">Illustrative data</p><p>These visualizations use synthetic data to demonstrate what real introspection would look like. They are clearly labeled as &quot;Illustrative&quot; in the UI. Real introspection requires model internals that Ollama doesn&#39;t expose.</p></div><h3 id="tools-tab" tabindex="-1">Tools Tab <a class="header-anchor" href="#tools-tab" aria-label="Permalink to &quot;Tools Tab&quot;">​</a></h3><p>A timeline of any tool calls the model made during the conversation, showing:</p><ul><li>Tool name and parameters</li><li>Execution result</li><li>Duration</li></ul><h3 id="agent-tab" tabindex="-1">Agent Tab <a class="header-anchor" href="#agent-tab" aria-label="Permalink to &quot;Agent Tab&quot;">​</a></h3><p>A state-flow graph showing how an agent-style prompt progressed through planning, tool calls, and synthesis steps.</p><h3 id="prompt-tab" tabindex="-1">Prompt Tab <a class="header-anchor" href="#prompt-tab" aria-label="Permalink to &quot;Prompt Tab&quot;">​</a></h3><p>An anatomy breakdown of your prompt showing:</p><ul><li>Identified sections (system, user, context, tools, examples)</li><li>Token counts per section</li><li>Overall structure analysis</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Session persistence</strong> — All conversations are stored in IndexedDB and survive browser refreshes.</li><li><strong>Model switching</strong> — You can switch models mid-session. The new model will see the full conversation history.</li><li><strong>Performance</strong> — The token store uses <code>shallowRef</code> for performance with thousands of tokens.</li></ul>',40)])])}const b=t(i,[["render",r]]);export{g as __pageData,b as default};
